import {tokenActions as actions} from './token-actions.mjs';
import {FEEDS,NETWORKS,buildPublicView,fetchPublicSource,mergeArticles,compareSnapshots,addressMatches,safeURL} from './public-radar.mjs';
import {contractForCopy,copyContract,axiomLink} from './contract-copy.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:'compact',maximumFractionDigits:1}).format(n),num=n=>n===null?'—':n.toLocaleString('en-US');
const ago=time=>!Number.isFinite(time)?'Unknown':Math.max(0,Math.round((Date.now()-time)/60000))<60?`${Math.max(0,Math.round((Date.now()-time)/60000))}m ago`:(Date.now()-time)<86400000?`${Math.floor((Date.now()-time)/3600000)}h ago`:`${Math.floor((Date.now()-time)/86400000)}d ago`;
const state={hours:24,group:'all',stage:'all',query:''};let expandedTrends=false,expandedCoins=false,loading=false,lastAttempt=0,toastTimer;
const dataset={articles:[],coins:[]},sourceState=new Map();let previous=null,current=null,baselineSet=false;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}
function metrics(items){return `<dl class="signal-metrics">${items.map(([name,value])=>`<div><dt>${esc(name)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`}
function tokens(n){const matches=addressMatches(n,dataset.coins);return matches.length?matches.map(c=>`<span class="token-match"><span class="token-tag">$${esc(c.symbol)} · CA match</span>${actions(c)}</span>`).join(''):'<span class="token-tag no-token">No verified token match</span>'}
function evidence(n){return n.posts.map(p=>`<article class="evidence-post"><div><span>${esc(p.publisher)}</span><time datetime="${new Date(p.time).toISOString()}">${esc(ago(p.time))}</time></div><p><a href="${esc(safeURL(p.url))}" target="_blank" rel="noopener noreferrer">${esc(p.title)} ↗</a></p></article>`).join('')}
function detail(title,body){$('#detail-title').textContent=title;$('#detail-body').innerHTML=body;$('#detail-dialog').showModal()}
function empty(message){return `<p class="empty-state">${esc(message)}</p>`}
function render(){
 const view=buildPublicView(dataset,state);
 $('#trend-count').textContent=view.trends.length;$('#coin-count').textContent=view.coins.length;$('#crossover-count').textContent=view.crossovers.length;
 $('#filter-status').textContent=`${view.trends.length} news signals · ${view.coins.length} coins · ${state.hours===72?'3-day':state.hours+'H'} news window${state.group!=='all'?' · '+state.group:''}${state.stage!=='all'?' · '+state.stage:''} · market metrics: 24H`;
 $('#trends').innerHTML=view.trends.slice(0,expandedTrends?20:3).map(n=>`<article class="signal-card"><div class="signal-top"><span class="rank">${String(n.rank).padStart(2,'0')}</span><div class="signal-name"><h3>${esc(n.title)}</h3></div></div><div class="tags"><span class="stage-tag">${n.stage===1?'LC1 candidate · cross-publisher coverage':'LC0 · raw news signal'}</span>${tokens(n)}</div><p class="signal-summary">${esc(n.summary)}</p>${metrics([['Publishers',n.sources],['Articles',n.mentions],['Latest',ago(n.latest)]])}<div class="signal-bottom"><span>First observed article ${esc(ago(n.first))}</span><div class="signal-actions"><a class="text-button" href="./narrative.html?id=${encodeURIComponent(n.id)}">Open research ↗</a><button class="text-button" data-timeline="${n.id}">Quick timeline</button></div></div></article>`).join('')||empty(loading&&!dataset.articles.length?'Loading public news…':'No articles match this window and filters. Try 24H or 3D. Feed availability is shown above.');
 $('#coins').innerHTML=view.coins.slice(0,expandedCoins?20:3).map(c=>`<article class="signal-card"><div class="signal-top"><span class="rank">${String(c.rank).padStart(2,'0')}</span><div class="signal-name"><h3>$${esc(c.symbol)}</h3><small>${esc(c.name)} · ${esc(c.chain)}</small></div>${actions(c)}</div><div class="tags"><span class="stage-tag">LC unclassified</span></div>${metrics([['Market cap',money(c.mc)],['Pool volume · 24H',money(c.volume)],['Pool buyers · 24H',num(c.buyers)]])}<div class="coin-context">Narrative / holder growth: unknown<br>Pool liquidity ${money(c.liquidity)} · pool created ${esc(ago(c.poolCreated))}</div><div class="signal-bottom"><span>${sourceState.get(c.network)?.status==='failed'?'Cached · ':''}Fetched ${esc(ago(c.fetchedAt))}</span></div></article>`).join('')||empty(loading&&!dataset.coins.length?'Loading market activity…':'No coins match these filters, or the market feed is unavailable. News groups and lifecycle stages are not inferred for unmatched coins.');
 for(const [selector,count,expanded,noun] of [['#trends-more',view.trends.length,expandedTrends,'signals'],['#coins-more',view.coins.length,expandedCoins,'coins']]){const b=$(selector);b.hidden=count<=3;b.textContent=expanded?'Show top 3':`View all ${count} ${noun}`;b.setAttribute('aria-expanded',expanded)}
 $('#crossovers').innerHTML=view.crossovers.map(c=>`<button type="button" class="crossover-card" data-match="${esc(c.id)}"><span class="crossover-direction">NEWS ↔ COIN · EXACT CA MATCH</span><strong>${esc(c.coin.symbol)} ↗</strong><span class="crossover-brief">${esc(c.narrative.title)}</span></button>`).join('')||'<p class="crossover-empty">No exact contract-address matches in the returned news and market sample. Origin and narrative lead time remain unknown.</p>';
 renderStatus();
}
function renderStatus(){
 $('#feed-status').innerHTML=[...FEEDS,...NETWORKS].map(s=>{const item=sourceState.get(s.id);return `<span class="feed-state ${item?.status==='failed'?'feed-failed':''}">${esc(s.name)}: ${item?item.status==='loaded'?`${item.count} ${s.url?'articles':'tokens'} · fetched ${esc(ago(item.at))}`:item.status==='failed'?esc(item.error)+(item.at?' · cached results retained':''):'loading':'waiting'}</span>`}).join('');
 $('#refresh-radar').disabled=loading;$('#refresh-radar').textContent=loading?'Refreshing…':'Refresh ↻';
}
function snapshot(){const view=buildPublicView(dataset,{hours:24});return {at:Date.now(),trends:view.trends.map(n=>({id:n.id,title:n.title,rank:n.rank})),coins:view.coins.map(c=>({id:c.id,title:'$'+c.symbol,rank:c.rank})),crossovers:view.crossovers.map(c=>({id:c.id,title:'$'+c.coin.symbol+' CA match'}))}}
function updateHistory(){
 if([...FEEDS,...NETWORKS].some(s=>sourceState.get(s.id)?.status!=='loaded'))return;
 if(!baselineSet){const value=read('meme-fast-public-snapshot-v1',null);previous=value&&['trends','coins','crossovers'].every(k=>Array.isArray(value[k])&&value[k].every(x=>x&&typeof x.id==='string'&&typeof x.title==='string'))?value:null;baselineSet=true}
 current=snapshot();save('meme-fast-public-snapshot-v1',current);
}
async function refresh(){
 if(loading)return;
 if(Date.now()-lastAttempt<60000){toast('Please allow one minute between refreshes.');return}
 loading=true;lastAttempt=Date.now();render();
 await Promise.allSettled([...FEEDS,...NETWORKS].map(async(s,index)=>{
  // Stagger market requests to respect the public provider's request budget.
  if(!s.url)await new Promise(resolve=>setTimeout(resolve,(index-FEEDS.length)*2200));
  const old=sourceState.get(s.id);sourceState.set(s.id,{...old,status:'loading'});renderStatus();
  try{const items=await fetchPublicSource(s);sourceState.set(s.id,{status:'loaded',count:items.length,at:Date.now()});
   if(s.url){dataset.articles=mergeArticles(dataset.articles,items);save('meme-fast-public-articles-v1',dataset.articles)}
   else {dataset.coins=[...dataset.coins.filter(c=>c.network!==s.id),...items];save('meme-fast-public-coins-v1',dataset.coins)}
  }catch(error){sourceState.set(s.id,{...old,status:'failed',error:error.message||'Could not reach feed.'})}
  render();
 }));
 loading=false;updateHistory();render();
}
function toast(message){$('#copy-status').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#copy-status').textContent='',4000)}
function showNarrative(id,timelineOnly=false){
 const n=buildPublicView(dataset,state).all.find(n=>n.id===id);if(!n)return;
 detail(n.title,`<div class="tags"><span class="stage-tag">${n.stage===1?'LC1 candidate':'LC0 raw news signal'}</span>${tokens(n)}</div><p class="detail-note">Public news coverage, not X-account spread. ${state.hours}H window. Grouped by shared headline terms; this is not semantic or bot analysis.</p>${metrics([['Publishers',n.sources],['Articles in window',n.mentions]])}${timelineOnly?`<ol class="timeline-list">${[...n.posts].reverse().map(p=>`<li><time>${esc(new Date(p.time).toLocaleString())}</time>${esc(p.publisher)} · <a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.title)} ↗</a></li>`).join('')}</ol>`:evidence(n)}`);
}
function showCoin(id){const c=dataset.coins.find(c=>c.id===id);if(!c)return;detail('$'+c.symbol+' · '+c.name,`<p class="detail-summary">${esc(c.chain)} · GeckoTerminal-listed contract</p><div class="contract-detail">${actions(c)}<code>${esc(c.contract_address)}</code></div>${metrics([['Market cap',money(c.mc)],['FDV (separate)',money(c.fdv)],['Pool liquidity',money(c.liquidity)]])}${metrics([['Pool volume · 24H',money(c.volume)],['Pool buyers · 24H',num(c.buyers)],['Pool buys / sells',num(c.buys)+' / '+num(c.sells)]])}<p class="detail-note">Fetched ${esc(new Date(c.fetchedAt).toLocaleString())}. One selected pool per token; buyers are not summed across pools. Pool creation is not token launch time. Holder counts, holder growth, origin, lifecycle and social-account counts are unavailable. A provider-listed contract is not an authenticity or safety endorsement.</p><p class="detail-summary"><a target="_blank" rel="noopener noreferrer" href="https://www.geckoterminal.com/${c.network}/pools/${encodeURIComponent(c.pool)}">View source pool ↗</a></p>`)}
async function copy(button){const c=dataset.coins.find(c=>c.id===button.dataset.copyCa),result=await copyContract(c,navigator.clipboard);if(result.status==='copied'){button.innerHTML='Copied ✓';toast(`${c.symbol} CA copied (${c.chain}).`);setTimeout(()=>{if(button.isConnected)button.innerHTML='CA ⧉'},1800)}else if(result.status==='manual'){$('#copy-address').value=result.address;$('#copy-note').textContent=`Copy ${c.symbol} on ${c.chain} below.`;$('#copy-dialog').showModal();$('#copy-address').focus();$('#copy-address').select()}else toast('No contract address is available.')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.dataset.hours){state.hours=Number(b.dataset.hours);document.querySelectorAll('[data-hours]').forEach(x=>x.setAttribute('aria-pressed',x===b));render()}if(b.dataset.stage){state.stage=b.dataset.stage;document.querySelectorAll('[data-stage]').forEach(x=>x.setAttribute('aria-pressed',x===b));render()}if(b.dataset.evidence)showNarrative(b.dataset.evidence);if(b.dataset.timeline)showNarrative(b.dataset.timeline,true);if(b.dataset.coin)showCoin(b.dataset.coin);if(b.dataset.copyCa)copy(b);if(b.dataset.match){const match=buildPublicView(dataset,state).crossovers.find(c=>c.id===b.dataset.match);if(match)detail('$'+match.coin.symbol+' · address match',`<div class="tags">${actions(match.coin)}</div><p class="detail-summary">An article contains this exact contract address. The feed does not establish whether the narrative preceded the token launch.</p>${evidence(match.narrative)}`)}});
$('#group').onchange=e=>{state.group=e.target.value;render()};$('#radar-search').oninput=e=>{state.query=e.target.value;render()};
$('#trends-more').onclick=()=>{expandedTrends=!expandedTrends;render()};$('#coins-more').onclick=()=>{expandedCoins=!expandedCoins;render()};$('#refresh-radar').onclick=refresh;
$('#changes-open').onclick=()=>{const changes=current?compareSnapshots(previous,current):[];detail('What changed',!current?'<p class="detail-summary">Waiting for a complete successful refresh before comparing rankings. A failed feed is not counted as disappearing activity.</p>':`<p class="detail-summary">${previous?'Since '+esc(new Date(previous.at).toLocaleString())+'.':'First complete snapshot saved. Return later to compare.'}</p>${changes.length?`<ul class="changes-list">${changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>`:previous?'<p>No ranking changes in the returned sample.</p>':''}<p class="detail-note">Uses the unfiltered 24H news view and 24H pool data. History is saved only in this browser.</p>`)};
$('#lifecycle-open').onclick=()=>detail('Lifecycle and public-feed coverage','<div class="lifecycle-list"><p>LC0: a raw news signal from one publisher.</p><p>LC1 candidate: matching headlines from multiple publishers. Syndication may still occur.</p><p>LC2: meme formation. LC3: early conversion. LC4: crowd expansion. LC5: saturation. LC6: decay / rotation.</p></div><p class="no-token-note">These public feeds cannot establish LC2–6 or independent X-account activity. Coins remain unclassified. An exact CA match links an article and token without asserting which came first.</p>');
const savedSources=read('meme-fast-radar-sources-v1',[]);let sources=Array.isArray(savedSources)?savedSources.filter(s=>s&&/^@[A-Za-z0-9_]{1,15}$/.test(s.handle)&&typeof s.category==='string'&&typeof s.group==='string'&&Number.isInteger(s.weight)&&s.weight>=1&&s.weight<=5):[];
function renderSources(){$('#source-list').innerHTML=sources.length?sources.map(s=>`<div class="source-row"><div><strong>${esc(s.handle)}</strong><small>${esc(s.category)} · ${esc(s.group)} · weight ${s.weight}/5</small></div><button data-remove-source="${esc(s.handle)}" aria-label="Remove ${esc(s.handle)}">Remove</button></div>`).join(''):empty('No X accounts saved. Public news feeds work independently of this watchlist.')}
$('#sources-open').onclick=()=>{renderSources();$('#sources-dialog').showModal()};
$('#source-form').onsubmit=e=>{e.preventDefault();const handle='@'+$('#source-handle').value.replace(/^@/,'');if(sources.some(s=>s.handle.toLowerCase()===handle.toLowerCase())){$('#source-status').textContent='Account already saved.';return}sources.push({handle,category:$('#source-category').value,group:$('#source-group').value,weight:Number($('#source-weight').value)});const saved=save('meme-fast-radar-sources-v1',sources);$('#source-status').textContent=saved?'Saved locally. X collection is not connected.':'Saved for this session; browser storage is unavailable.';$('#source-handle').value='';renderSources()};
document.addEventListener('click',e=>{const b=e.target.closest('[data-remove-source]');if(b){sources=sources.filter(s=>s.handle!==b.dataset.removeSource);save('meme-fast-radar-sources-v1',sources);renderSources()}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
const cached=read('meme-fast-public-articles-v1',[]);
if(Array.isArray(cached))dataset.articles=mergeArticles([],cached.filter(p=>p&&typeof p.id==='string'&&safeURL(p.url)&&typeof p.title==='string'&&typeof p.summary==='string'&&typeof p.publisher==='string'&&Number.isFinite(p.time)&&FEEDS.some(f=>f.id===p.feed)));
render();refresh();setInterval(()=>{if(!document.hidden)refresh()},300000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&Date.now()-lastAttempt>300000)refresh()});
